# check $schema#arrayTypes (.'$schema#arrayTypes')
sub json_model_7($$$)
{
    my ($val, $path, $rep) = @_;
    # .'$schema#arrayTypes'
    # .'$schema#arrayTypes'.'@'
    my $res = jm_is_array($val);
    if ($res)
